examples.sparql:
PREFIX gvp: <http://vocab.getty.edu/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX schema: <http://schema.org/>
PREFIX ulan: <http://vocab.getty.edu/ulan/>
SELECT ?pupil ?name ?bio WHERE {
  ulan:500011051 gvp:teacherOf ?pupil .
  OPTIONAL { ?pupil skos:prefLabel ?name }
  OPTIONAL { ?pupil schema:description ?bio }
}

PREFIX gvp: <http://vocab.getty.edu/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX ulan: <http://vocab.getty.edu/ulan/>
SELECT DISTINCT ?descendant ?name WHERE {
  ulan:500011051 gvp:teacherOf+ ?descendant .
  OPTIONAL { ?descendant skos:prefLabel ?name }
} LIMIT 500

PREFIX gvp: <http://vocab.getty.edu/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?masterName ?pupilName ?grandPupilName WHERE {
  ?master gvp:teacherOf ?pupil . ?pupil gvp:teacherOf ?grandPupil .
  ?master skos:prefLabel ?masterName . ?pupil skos:prefLabel ?pupilName . ?grandPupil skos:prefLabel ?grandPupilName .
} LIMIT 100

PREFIX gvp: <http://vocab.getty.edu/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX schema: <http://schema.org/>
SELECT ?teacher ?name ?bio (COUNT(?pupil) AS ?pupils) WHERE {
  ?teacher gvp:teacherOf ?pupil .
  OPTIONAL { ?teacher skos:prefLabel ?name } OPTIONAL { ?teacher schema:description ?bio }
} GROUP BY ?teacher ?name ?bio ORDER BY DESC(?pupils) LIMIT 25

PREFIX gvp: <http://vocab.getty.edu/ontology#>
SELECT ?nationality (COUNT(*) AS ?teachingLinks) WHERE {
  ?teacher gvp:teacherOf ?pupil ; gvp:nationality ?nationality .
} GROUP BY ?nationality ORDER BY DESC(?teachingLinks) LIMIT 25

