}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?manuscript ?iiif WHERE {
  ?m wdt:P6108 ?iiif ; rdfs:label ?manuscript .
} LIMIT 30

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?place (COUNT(?m) AS ?manuscripts) WHERE {
  ?m wdt:P1071 ?p . ?p rdfs:label ?place .
} GROUP BY ?place ORDER BY DESC(?manuscripts)

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?person ?wikidata WHERE {
  ?p owl:sameAs ?wikidata ; rdfs:label ?person .
} ORDER BY ?person

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?person ?born ?died WHERE {
  ?p owl:sameAs ?wd ; rdfs:label ?person .
  SERVICE <https://query.wikidata.org/sparql> {
    VALUES ?wd { <http://www.wikidata.org/entity/Q166876> <http://www.wikidata.org/entity/Q184500> <http://www.wikidata.org/entity/Q2609522> }
    ?wd wdt:P569 ?born .
    OPTIONAL { ?wd wdt:P570 ?died }
  }
}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?manuscript ?date WHERE {
  ?m wdt:P571 ?date ; rdfs:label ?manuscript .
}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
