  ?s p:collectedBy ?c ; dwc:scientificName ?species .
  OPTIONAL { ?s p:taxon ?sp . ?sp p:parentTaxon+ ?f . ?f p:rank "family" ; rdfs:label ?family }
  OPTIONAL { ?s p:foundIn ?pl . ?pl rdfs:label ?place }
  OPTIONAL { ?s p:preview ?photo }
} LIMIT 30

PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
