PREFIX la: <https://lineara.xyz/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?sign (COUNT(?i) AS ?attestations) WHERE {
  ?i la:sign ?s . ?s rdfs:label ?sign .
} GROUP BY ?sign ORDER BY DESC(?attestations) LIMIT 25

PREFIX la: <https://lineara.xyz/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?site (COUNT(?i) AS ?documents) WHERE {
  ?i la:site ?s . ?s rdfs:label ?site .
} GROUP BY ?site ORDER BY DESC(?documents)

PREFIX la: <https://lineara.xyz/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?inscription ?model3d ?paito WHERE {
  ?i rdfs:label ?inscription .
  OPTIONAL { ?i la:model3d ?model3d }
  OPTIONAL { ?i la:paito ?paito }
  FILTER(BOUND(?model3d) || BOUND(?paito))
} ORDER BY ?inscription

PREFIX la: <https://lineara.xyz/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?word (COUNT(DISTINCT ?i) AS ?documents) WHERE {
  ?i la:word ?w . ?w rdfs:label ?word .
} GROUP BY ?word ORDER BY DESC(?documents) LIMIT 25

PREFIX la: <https://lineara.xyz/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?inscription ?transliteration WHERE {
  ?i la:transliteration ?transliteration ; rdfs:label ?inscription .
  FILTER(CONTAINS(?transliteration, "KU-RO"))
}

PREFIX la: <https://lineara.xyz/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT {
  ?i la:word ?w . ?i rdfs:label ?inscription . ?w rdfs:label ?word .
} WHERE {
  ?w rdfs:label "SA-RA₂" . ?i la:word ?w ; rdfs:label ?inscription .
  ?w rdfs:label ?word .
}

PREFIX nmo: <http://nomisma.org/ontology#>
PREFIX nm: <http://nomisma.org/id/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?type ?label ?mintName WHERE {
  ?type a nmo:TypeSeriesItem ; rdfs:label ?label ;
        nmo:hasAuthority nm:alexander_iii ; nmo:hasMaterial nm:ar ; nmo:hasDenomination nm:tetradrachm ; nmo:hasMint ?mint .
  ?mint rdfs:label ?mintName .
} ORDER BY ?mintName LIMIT 50

PREFIX nmo: <http://nomisma.org/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?mintName (COUNT(?type) AS ?types) WHERE {
  ?type a nmo:TypeSeriesItem ; nmo:hasMint ?mint .
  ?mint rdfs:label ?mintName .
} GROUP BY ?mintName ORDER BY DESC(?types) LIMIT 15

PREFIX nmo: <http://nomisma.org/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?authName (COUNT(?type) AS ?types) WHERE {
  ?type a nmo:TypeSeriesItem ; nmo:hasAuthority ?auth .
  ?auth rdfs:label ?authName .
} GROUP BY ?authName ORDER BY DESC(?types)

PREFIX nmo: <http://nomisma.org/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?mintName (COUNT(DISTINCT ?auth) AS ?rulers) (GROUP_CONCAT(DISTINCT ?authName; SEPARATOR=", ") AS ?who) WHERE {
  ?type a nmo:TypeSeriesItem ; nmo:hasMint ?mint ; nmo:hasAuthority ?auth .
  ?mint rdfs:label ?mintName . ?auth rdfs:label ?authName .
} GROUP BY ?mintName HAVING(COUNT(DISTINCT ?auth) >= 3) ORDER BY DESC(?rulers)

PREFIX nmo: <http://nomisma.org/ontology#>
PREFIX nm: <http://nomisma.org/id/>
CONSTRUCT { ?auth nmo:hasMint ?mint . } WHERE {
  ?tc a nmo:TypeSeriesItem ; nmo:hasAuthority nm:cassander ; nmo:hasMint ?mint .
  ?t a nmo:TypeSeriesItem ; nmo:hasMint ?mint ; nmo:hasAuthority ?auth .
}

