examples.sparql:
PREFIX wdt: <http://data.mimotext.uni-trier.de/prop/direct/>
PREFIX wd:  <http://data.mimotext.uni-trier.de/entity/>
SELECT ?kind (COUNT(DISTINCT ?x) AS ?n) WHERE {
  VALUES (?class ?kind) { (wd:Q2 "literary work") (wd:Q10 "person") (wd:Q20 "thematic concept") (wd:Q26 "spatial concept") }
  ?x wdt:P2 ?class .
} GROUP BY ?kind ORDER BY DESC(?n)

PREFIX wdt: <http://data.mimotext.uni-trier.de/prop/direct/>
PREFIX rdfs:<http://www.w3.org/2000/01/rdf-schema#>
SELECT ?theme (COUNT(DISTINCT ?work) AS ?novels) WHERE {
  ?work wdt:P36 ?t . ?t rdfs:label ?theme . FILTER(LANG(?theme)="en")
} GROUP BY ?theme ORDER BY DESC(?novels) LIMIT 15

PREFIX wdt: <http://data.mimotext.uni-trier.de/prop/direct/>
PREFIX rdfs:<http://www.w3.org/2000/01/rdf-schema#>
SELECT ?work ?year ?genre WHERE {
  ?author rdfs:label ?aName . FILTER(LANG(?aName)="en" && CONTAINS(?aName,"Baculard"))
  ?w wdt:P5 ?author ; rdfs:label ?work . FILTER(LANG(?work)="en")
  OPTIONAL { ?w wdt:P9 ?d . BIND(YEAR(?d) AS ?year) }
  OPTIONAL { ?w wdt:P12 ?g . ?g rdfs:label ?genre FILTER(LANG(?genre)="en") }
} ORDER BY ?year

PREFIX wdt: <http://data.mimotext.uni-trier.de/prop/direct/>
PREFIX rdfs:<http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT {
  ?work wdt:P5 ?author . ?work wdt:P12 ?genre .
  ?author rdfs:label ?aL . ?work rdfs:label ?wL . ?genre rdfs:label ?gL .
} WHERE {
  ?author rdfs:label ?aL . FILTER(LANG(?aL)="en" && CONTAINS(?aL,"Baculard"))
  ?work wdt:P5 ?author ; rdfs:label ?wL . FILTER(LANG(?wL)="en")
  OPTIONAL { ?work wdt:P12 ?genre . ?genre rdfs:label ?gL FILTER(LANG(?gL)="en") }
}

