SELECT ?p ?o WHERE {
  <http://ldf.fi/mmm/manifestation_singleton/sdbm_orphan_212926> ?p ?o
}

PREFIX crm: <http://erlangen-crm.org/current/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?text ?language WHERE {
  <http://ldf.fi/mmm/manifestation_singleton/sdbm_orphan_212926> crm:P128_carries ?expr .
  ?expr skos:prefLabel ?text ; crm:P72_has_language/skos:prefLabel ?language .
}

PREFIX crm: <http://erlangen-crm.org/current/>
PREFIX mmm: <http://ldf.fi/schema/mmm/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX wgs: <http://www.w3.org/2003/01/geo/wgs84_pos#>
SELECT ?stage ?place ?lat ?long WHERE {
  BIND(<http://ldf.fi/mmm/manifestation_singleton/sdbm_orphan_212926> AS ?ms)
  { ?ms crm:P51_has_former_or_current_owner ?owner . ?owner skos:prefLabel ?place . BIND("owned by" AS ?stage) }
  UNION
  { ?ms mmm:last_known_location ?loc . ?loc skos:prefLabel ?place .
    OPTIONAL { ?loc wgs:lat ?lat ; wgs:long ?long } BIND("last known at" AS ?stage) }
}

PREFIX crm: <http://erlangen-crm.org/current/>
PREFIX mmm: <http://ldf.fi/schema/mmm/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?work ?ownerName ?shelfmark WHERE {
  <http://ldf.fi/mmm/manifestation_singleton/sdbm_orphan_212926>
    mmm:manuscript_work/skos:prefLabel ?work ;
    mmm:catalog_or_lot_number ?shelfmark ;
    crm:P51_has_former_or_current_owner/skos:prefLabel ?ownerName .
}

PREFIX crm: <http://erlangen-crm.org/current/>
PREFIX mmm: <http://ldf.fi/schema/mmm/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
CONSTRUCT {
  ?ms mmm:manuscript_work ?work ; crm:P51_has_former_or_current_owner ?owner ;
      crm:P45_consists_of ?material ; mmm:catalog_or_lot_number ?shelf .
} WHERE {
  BIND(<http://ldf.fi/mmm/manifestation_singleton/sdbm_orphan_212926> AS ?ms)
  OPTIONAL { ?ms mmm:manuscript_work/skos:prefLabel ?work }
  OPTIONAL { ?ms crm:P51_has_former_or_current_owner/skos:prefLabel ?owner }
  OPTIONAL { ?ms crm:P45_consists_of ?material }
  OPTIONAL { ?ms mmm:catalog_or_lot_number ?shelf }
}

PREFIX crm: <http://erlangen-crm.org/current/>
PREFIX mmm: <http://ldf.fi/schema/mmm/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT DISTINCT ?msLabel ?place WHERE {
  ?ms crm:P128_carries ?e .
  ?e crm:P72_has_language <http://ldf.fi/mmm/language/sdbm_1> , <http://ldf.fi/mmm/language/sdbm_3> , <http://ldf.fi/mmm/language/sdbm_4> .
  ?ms skos:prefLabel ?msLabel .
  OPTIONAL { ?ms mmm:last_known_location/skos:prefLabel ?place }
  FILTER(?ms != <http://ldf.fi/mmm/manifestation_singleton/sdbm_orphan_212926>)
} LIMIT 100

PREFIX crm: <http://erlangen-crm.org/current/>
PREFIX mmm: <http://ldf.fi/schema/mmm/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?msLabel (SAMPLE(?text) AS ?work) WHERE {
  ?ms crm:P51_has_former_or_current_owner <http://ldf.fi/mmm/actor/sdbm_38068> ; skos:prefLabel ?msLabel .
  OPTIONAL { ?ms mmm:manuscript_work/skos:prefLabel ?text }
} GROUP BY ?ms ?msLabel

PREFIX crm: <http://erlangen-crm.org/current/>
PREFIX mmm: <http://ldf.fi/schema/mmm/>
SELECT ?ms ?shelfmark WHERE {
  ?ms crm:P70i_is_documented_in <http://ldf.fi/mmm/collection/sdbm_33357> ;
      mmm:catalog_or_lot_number ?shelfmark .
} LIMIT 100

PREFIX crm: <http://erlangen-crm.org/current/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?placeName (COUNT(?ms) AS ?manuscripts) WHERE {
  ?prod a crm:E12_Production ; crm:P108_has_produced ?ms ; crm:P7_took_place_at ?place .
  ?place skos:prefLabel ?placeName .
} GROUP BY ?placeName ORDER BY DESC(?manuscripts) LIMIT 25

