PREFIX su: <https://w3id.org/rete/subtitles#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?language ?cues WHERE {
  ?t a su:SubtitleTrack ; rdfs:label ?language ; su:cueCount ?cues .
} ORDER BY DESC(?cues) ?language

PREFIX su: <https://w3id.org/rete/subtitles#>
SELECT ?language ?text WHERE {
  ?line a su:Line ; su:start ?s ; su:text ?text .
  FILTER(?s >= 23 && ?s < 24)
  BIND(LANG(?text) AS ?language)
} ORDER BY ?language

PREFIX su: <https://w3id.org/rete/subtitles#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?start ?subtitle WHERE {
  ?c a su:Cue ; dct:language "ja" ; su:start ?start ; su:text ?subtitle .
} ORDER BY ?start

PREFIX su: <https://w3id.org/rete/subtitles#>
SELECT ?start ?language ?text WHERE {
  ?c a su:Cue ; su:start ?start ; su:text ?text .
  FILTER(CONTAINS(LCASE(STR(?text)), "robot"))
  BIND(LANG(?text) AS ?language)
} ORDER BY ?start ?language

PREFIX mtg: <https://w3id.org/rete/mtg#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?type (COUNT(?c) AS ?cards) WHERE {
  ?c a mtg:Card ; a ?t .
  ?t rdfs:subClassOf mtg:Card ; rdfs:label ?type .
} GROUP BY ?type ORDER BY DESC(?cards)

PREFIX mtg: <https://w3id.org/rete/mtg#>
PREFIX schema: <http://schema.org/>
SELECT ?image ?card ?rank WHERE {
  ?c a mtg:Creature ; schema:name ?card ; mtg:image ?image ; mtg:edhrecRank ?rank ;
     mtg:color <https://w3id.org/rete/mtg/color/R> ;
     mtg:keyword <https://w3id.org/rete/mtg/keyword/flying> ;
     mtg:legalIn <https://w3id.org/rete/mtg/format/modern> .
} ORDER BY ?rank LIMIT 24

PREFIX mtg: <https://w3id.org/rete/mtg#>
PREFIX schema: <http://schema.org/>
SELECT ?image ?card ?text WHERE {
  ?c schema:name ?card ; mtg:image ?image ; mtg:oracleText ?text .
  FILTER(CONTAINS(LCASE(?text), "draw two cards"))
} LIMIT 24

PREFIX mtg: <https://w3id.org/rete/mtg#>
PREFIX schema: <http://schema.org/>
SELECT ?image ?card ?rank WHERE {
  ?c mtg:subtype <https://w3id.org/rete/mtg/subtype/dragon> ; schema:name ?card ; mtg:image ?image ; mtg:edhrecRank ?rank .
} ORDER BY ?rank LIMIT 24

PREFIX mtg: <https://w3id.org/rete/mtg#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?color (COUNT(?c) AS ?cards) WHERE {
  ?c mtg:color ?col . ?col rdfs:label ?color .
} GROUP BY ?color ORDER BY DESC(?cards)

PREFIX mtg: <https://w3id.org/rete/mtg#>
PREFIX schema: <http://schema.org/>
SELECT ?image ?card ?rank WHERE {
  ?c schema:name ?card ; mtg:image ?image ; mtg:edhrecRank ?rank .
} ORDER BY ?rank LIMIT 24

PREFIX mtg: <https://w3id.org/rete/mtg#>
PREFIX schema: <http://schema.org/>
SELECT ?image ?card ?rank WHERE {
  ?c mtg:printedIn <https://w3id.org/rete/mtg/set/LEA> ; schema:name ?card ; mtg:image ?image .
  OPTIONAL { ?c mtg:edhrecRank ?rank }
} ORDER BY ?rank LIMIT 24

PREFIX mtgg: <https://w3id.org/rete/mtg/game#>
PREFIX mtg: <https://w3id.org/rete/mtg#>
PREFIX mtgo: <https://cmdoret.net/mtg_ontology/>
PREFIX schema: <http://schema.org/>
SELECT ?card ?cost ?available WHERE {
  { SELECT (COUNT(?land) AS ?available) WHERE {
      ?lm mtgg:inState <https://w3id.org/rete/mtg/game/s1> ; mtgg:object ?land ; mtgg:zone <https://w3id.org/rete/mtg/game/battlefield> ; mtgg:tapped false .
      ?land mtgg:controller <https://w3id.org/rete/mtg/game/alice> ; mtgg:ofCard ?lc . ?lc mtgg:producesMana ?col . } }
  ?hm mtgg:inState <https://w3id.org/rete/mtg/game/s1> ; mtgg:object ?i ; mtgg:zone <https://w3id.org/rete/mtg/game/aliceHand> .
  ?i mtgg:ofCard ?c . ?c a mtgo:Instant ; schema:name ?card ; mtg:manaValue ?cost .
  FILTER(?cost <= ?available)
}

PREFIX mtgg: <https://w3id.org/rete/mtg/game#>
SELECT ?instance (COUNT(?z) AS ?zones) WHERE {
  ?m a mtgg:ZoneMembership ; mtgg:inState <https://w3id.org/rete/mtg/game/s1> ; mtgg:object ?instance ; mtgg:zone ?z .
} GROUP BY ?instance HAVING (COUNT(?z) != 1)

PREFIX schema: <http://schema.org/>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT (MIN(STR(?img)) AS ?image) ?title (SAMPLE(?d) AS ?description) (SAMPLE(?f) AS ?from) (SAMPLE(?t) AS ?to) (SAMPLE(?i) AS ?id) WHERE {
  ?doc schema:name ?title ;
       schema:image ?img .
  OPTIONAL { ?doc schema:description ?d }
  OPTIONAL { ?doc schema:startDate ?f }
  OPTIONAL { ?doc schema:endDate ?t }
  OPTIONAL { ?doc dct:identifier ?i }
} GROUP BY ?doc ?title LIMIT 60

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX schema: <http://schema.org/>
SELECT ?wkt ?title WHERE {
  ?d geo:asWKT ?wkt ;
     schema:name ?title .
} LIMIT 4000

PREFIX schema: <http://schema.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?province (COUNT(?d) AS ?files) WHERE {
  ?d schema:contentLocation ?p .
  ?p rdfs:label ?province .
} GROUP BY ?province ORDER BY DESC(?files)

PREFIX schema: <http://schema.org/>
PREFIX arx: <https://w3id.org/rete/arxiu#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT (MIN(STR(?img)) AS ?image) ?title (SAMPLE(?d) AS ?description) (SAMPLE(?link) AS ?record) WHERE {
  ?doc schema:name ?title ;
       schema:image ?img ;
       dct:identifier ?i .
  FILTER(CONTAINS(LCASE(STR(?title)), "conca de barber") || CONTAINS(LCASE(STR(?title)), "espluga de francol"))
  OPTIONAL { ?doc schema:description ?d }
  BIND(CONCAT("https://arxiusenlinia.cultura.gencat.cat/#/cercabasica/resultats?text=", ENCODE_FOR_URI(STR(?i))) AS ?link)
} GROUP BY ?doc ?title LIMIT 60

PREFIX schema: <http://schema.org/>
SELECT ?archive (COUNT(?u) AS ?units) (COUNT(?i) AS ?scans) WHERE {
  ?u a schema:ArchiveComponent ; schema:holdingArchive ?a .
  ?a schema:name ?archive .
  OPTIONAL { ?u schema:image ?i }
} GROUP BY ?archive ORDER BY DESC(?units)

PREFIX schema: <http://schema.org/>
SELECT ?image ?title ?archive WHERE {
  ?u schema:image ?image ; schema:name ?title ; schema:holdingArchive ?a .
  ?a schema:name ?archive .
} LIMIT 30

PREFIX schema: <http://schema.org/>
SELECT ?image ?title ?start WHERE {
  ?u schema:startDate ?start ; schema:name ?title .
  OPTIONAL { ?u schema:image ?image }
} ORDER BY ?start LIMIT 24

PREFIX schema: <http://schema.org/>
SELECT ?image ?title ?desc WHERE {
  ?u schema:description ?desc ; schema:name ?title .
  OPTIONAL { ?u schema:image ?image }
  FILTER(CONTAINS(LCASE(?desc), "tarragona"))
} LIMIT 24

PREFIX schema: <http://schema.org/>
PREFIX arx: <https://w3id.org/rete/arxiu#>
SELECT ?image ?title ?original WHERE {
  ?u schema:image ?image ; schema:name ?title ; arx:originalImage ?original .
} LIMIT 20

PREFIX schema: <http://schema.org/>
PREFIX arx: <https://w3id.org/rete/arxiu#>
SELECT ?image ?title ?original WHERE {
  ?u arx:contentType "PDF" ; schema:name ?title ; arx:originalImage ?original .
  OPTIONAL { ?u schema:image ?image }
} LIMIT 24

PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?class (COUNT(*) AS ?n) WHERE {
  ?s a ?class .
  FILTER(STRSTARTS(STR(?class), STR(dcite:)))
} GROUP BY ?class ORDER BY DESC(?n)

PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?t ?name ?orcid WHERE {
  ?w dcite:creator ?p ; dcite:title ?t .
  ?p dcite:orcid ?orcid ; dcite:agentName ?name .
} LIMIT 30

SELECT ?p ?o WHERE {
  <https://doi.org/10.5281/zenodo.8435696> ?p ?o .
}

PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?v WHERE {
  ?v dcite:isVersionOf <https://doi.org/10.5281/zenodo.597466> .
} LIMIT 200

PREFIX dcite: <https://w3id.org/rete/datacite#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT {
  ?v dcite:isVersionOf ?c .
  ?v rdfs:label ?vl .
} WHERE {
  VALUES ?c { <https://doi.org/10.5281/zenodo.597466> }
  ?v dcite:isVersionOf ?c .
  OPTIONAL { ?v dcite:title ?vl }
} LIMIT 40

PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?y (COUNT(?s) AS ?n) WHERE {
  ?s a <https://w3id.org/rete/zenodo#Record> ; dcite:publicationYear ?y .
} GROUP BY ?y ORDER BY ?y

SELECT ?class (COUNT(*) AS ?n) WHERE {
  ?s a ?class .
  FILTER(STRSTARTS(STR(?class), "https://w3id.org/rete/"))
} GROUP BY ?class ORDER BY DESC(?n)

SELECT ?family (COUNT(*) AS ?n) WHERE {
  ?s <http://rs.tdwg.org/dwc/terms/family> ?family .
} GROUP BY ?family ORDER BY DESC(?n) LIMIT 25

PREFIX dcite: <https://w3id.org/rete/datacite#>
PREFIX zen: <https://w3id.org/rete/zenodo#>
SELECT ?t ?iiif WHERE {
  ?s <http://rs.tdwg.org/dwc/terms/family> "Cerambycidae" ;
     dcite:title ?t .
  OPTIONAL { ?s zen:iiifManifest ?iiif }
} LIMIT 40

PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?rel ?o WHERE {
  <https://doi.org/10.5281/zenodo.8436503> ?rel ?o .
  FILTER(?rel IN (dcite:isPartOf, dcite:isVersionOf, dcite:cites, dcite:references))
}

PREFIX dcite: <https://w3id.org/rete/datacite#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT {
  ?t dcite:isPartOf ?art .
  ?t rdfs:label ?tl .
} WHERE {
  VALUES ?art { <https://doi.org/10.11646/zootaxa.5353.2.3> }
  ?t dcite:isPartOf ?art .
  OPTIONAL { ?t dcite:title ?tl }
} LIMIT 40

PREFIX gtr: <https://w3id.org/rete/gotriple#>
SELECT ?class (COUNT(*) AS ?n) WHERE {
  ?s a ?class .
  FILTER(STRSTARTS(STR(?class), STR(gtr:)))
} GROUP BY ?class ORDER BY DESC(?n)

PREFIX gtr: <https://w3id.org/rete/gotriple#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?label (COUNT(?d) AS ?n) WHERE {
  ?d gtr:inDiscipline ?disc .
  ?disc skos:prefLabel ?label .
} GROUP BY ?disc ?label ORDER BY DESC(?n)

PREFIX gtr: <https://w3id.org/rete/gotriple#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?title WHERE {
  ?d gtr:knowsAbout <http://semantics.gr/authorities/SSH-LCSH/sh85040989> ;
     rdfs:label ?title .
} LIMIT 50

PREFIX gtr: <https://w3id.org/rete/gotriple#>
SELECT ?title ?url WHERE {
  ?d gtr:inDiscipline gtr:discipline-droit ;
     gtr:conditionsOfAccess "acr_open-access" ;
     gtr:fullTextUrl ?url ;
     gtr:title ?title .
} LIMIT 40

PREFIX gtr: <https://w3id.org/rete/gotriple#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT {
  ?d gtr:knowsAbout ?s .
  ?d rdfs:label ?dl .
  ?s rdfs:label ?sl .
} WHERE {
  VALUES ?d { <https://doi.org/10.33899/radab.1972.166508> }
  OPTIONAL { ?d rdfs:label ?dl }
  ?d gtr:knowsAbout ?s .
  OPTIONAL { ?s rdfs:label ?sl }
}
